{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "“普通”とか“あたりまえ”ってなんだろう",
        "今 手にある物差しでは",
        "全然上手く測れなくって",
        "吐いては また吸い込んだ不安に",
        "僕は為すがまま立ち尽くして"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "不器用で 空回って",
        "傷つくことから逃げている",
        "現実とノートで行ったり来たり 慰めて",
        "あぁ",
        "なんて生きづらい世界なんだろう",
        "だけど だけど"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "ぜんぶ ぜんぶ 僕だから",
        "うじうじ しくしく 僕だから",
        "ぜんぶ ぜんぶ 抱きしめて",
        "少し眠ろう",
        "痛いの痛いの飛んでゆけ",
        "悲しみにすべてを奪われないように",
        "僕は 僕の味方でいようよ",
        "まだまだ長い道の途中",
        "ちょっとくらい休憩したって",
        "誰にも叱られはしないから"
      ]
    }
  ],
  "section": "V1",
  "phrases": [
    {
      "id": "V1-01",
      "ja": "“普通”とか“あたりまえ”ってなんだろう",
      "budget": {
        "min": 13,
        "max": 13
      },
      "pattern": [
        10,
        3
      ]
    },
    {
      "id": "V1-02",
      "ja": "今 手にある物差しでは",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": null
    },
    {
      "id": "V1-03",
      "ja": "全然上手く測れなくって",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": null
    },
    {
      "id": "V1-04",
      "ja": "吐いては また吸い込んだ不安に",
      "budget": {
        "min": 14,
        "max": 14
      },
      "pattern": [
        10,
        4
      ]
    },
    {
      "id": "V1-05",
      "ja": "僕は為すがまま立ち尽くして",
      "budget": {
        "min": 14,
        "max": 14
      },
      "pattern": [
        12,
        2
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "平凡 普通 到底是什么 我一直在问"
        },
        {
          "id": "V1-02",
          "zh": "手里握着 这把尺子 量不清"
        },
        {
          "id": "V1-03",
          "zh": "怎么都量不出自己的形状"
        },
        {
          "id": "V1-04",
          "zh": "吐一口气 又吸进 不安的潮水"
        },
        {
          "id": "V1-05",
          "zh": "我只能 站在原地 一动不动"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "“普通”或是“理所当然”究竟是什么"
        },
        {
          "id": "V1-02",
          "zh": "用此刻手中的这把尺子"
        },
        {
          "id": "V1-03",
          "zh": "完全无法好好地丈量"
        },
        {
          "id": "V1-04",
          "zh": "吐出又再吸入的不安里"
        },
        {
          "id": "V1-05",
          "zh": "我任其摆布呆立不动"
        }
      ]
    }
  ]
}

